alter policy diary_photo_read on storage.objects using (bucket_id='diary-photos' and exists(select 1 from public.works w where w.id::text=(storage.foldername(storage.objects.name))[1])); alter policy diary_photo_upload on storage.objects with check (bucket_id='diary-photos' and exists(select 1 from public.works w where w.id::text=(storage.foldername(storage.objects.name))[1] and public.can_access_work(w.id,true)));
